<?php $labels=['pending'=>'بانتظار المراجعة','approved'=>'منشورة','spam'=>'مزعجة','trash'=>'المحذوفة','all'=>'الكل']; ?>
<div class="admin-page-head"><div><span class="eyebrow">إدارة التفاعل</span><h1>تعليقات المقالات</h1><p>راجع التعليقات، انشر المناسب، وانقل الرسائل المزعجة دون حذفها مباشرة.</p></div></div>
<div class="admin-tabs"><?php foreach($labels as $k=>$v):?><a class="<?=$status===$k?'active':''?>" href="/admin/comments?status=<?=$k?>"><?=$v?><?php if(isset($counts[$k])):?><b><?=number_format($counts[$k])?></b><?php endif;?></a><?php endforeach;?></div>
<div class="comment-admin-list"><?php if(!$comments):?><div class="empty-state">لا توجد تعليقات في هذا القسم.</div><?php endif;?><?php foreach($comments as $c):?><article class="admin-comment-card"><header><div><strong><?=e($c['author_name']?:'زائر')?></strong><small><?=e($c['author_email']??'')?> · <?=e($c['created_at'])?></small></div><span class="status-pill"><?=e($labels[$c['status']]??$c['status'])?></span></header><p><?=nl2br(e($c['content']))?></p><footer><a target="_blank" href="<?=e(locale_url($c['locale']?:default_locale(),'article/'.$c['article_slug']))?>#comment-<?=(int)$c['id']?>"><?=e($c['article_title']?:'المقال')?> ↗</a><div class="comment-actions"><?php foreach(['approve'=>'نشر','pending'=>'مراجعة','spam'=>'Spam','trash'=>'حذف مؤقت'] as $a=>$lab):?><form method="post" action="/admin/comments/action"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$c['id']?>"><input type="hidden" name="action" value="<?=$a?>"><button type="submit"><?=$lab?></button></form><?php endforeach;?><?php if($c['status']==='trash'):?><form method="post" action="/admin/comments/delete" onsubmit="return confirm('حذف نهائي؟')"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="danger">حذف نهائي</button></form><?php endif;?></div></footer></article><?php endforeach;?></div>
<section class="dashboard-card" id="comment-settings"><h2>إعدادات التعليقات</h2><form method="post" action="/admin/comments/settings" class="settings-form"><?=csrf_field()?>
<?php foreach(['comments_enabled'=>'تشغيل التعليقات','comments_require_moderation'=>'مراجعة التعليقات قبل النشر','comments_registered_autoapprove'=>'نشر تعليقات الأعضاء المسجلين مباشرة','comments_allow_guests'=>'السماح للزوار بالتعليق','comments_allow_replies'=>'السماح بالردود'] as $k=>$lab):?><label class="switch-row"><input type="checkbox" name="<?=$k?>" <?=setting($k,'1')==='1'?'checked':''?>><span><strong><?=$lab?></strong></span></label><?php endforeach;?>
<div class="form-grid"><label>أقصى عدد روابط<input type="number" min="0" max="20" name="comments_max_links" value="<?=e(setting('comments_max_links','2'))?>"></label><label>الفاصل بين التعليقات بالثواني<input type="number" min="10" max="3600" name="comments_rate_seconds" value="<?=e(setting('comments_rate_seconds','45'))?>"></label></div><label>كلمات محظورة <small>افصل بفاصلة أو سطر جديد</small><textarea name="comments_blocked_words" rows="5"><?=e(setting('comments_blocked_words',''))?></textarea></label><button class="btn btn-primary" type="submit">حفظ الإعدادات</button></form></section>
